-- Confirm the cleaned sample state: no leave requests or notifications are seeded.

-- Keep the localhost sample data free of demo remarks. Report attendance-based
-- late and absence amounts as deductions while preserving the same net pay.
UPDATE `payslips`
SET `gross_pay` = ROUND(COALESCE(`basic_pay`, 0) + COALESCE(`paid_leave_pay`, 0) + COALESCE(`late_deduction`, 0) + COALESCE(`absence_deduction`, 0), 2),
    `total_deductions` = COALESCE(`total_deductions`, 0) + COALESCE(`late_deduction`, 0) + COALESCE(`absence_deduction`, 0),
    `remarks` = NULL
WHERE `payroll_batch_id` BETWEEN 1 AND 7 AND `payslip_type` = 'regular';

UPDATE `payroll_batches` b
SET b.`total_gross` = COALESCE(b.`total_gross`, 0) + (
        SELECT COALESCE(SUM(COALESCE(p.`late_deduction`, 0) + COALESCE(p.`absence_deduction`, 0)), 0)
        FROM `payslips` p WHERE p.`payroll_batch_id` = b.`id`
    ),
    b.`total_deductions` = COALESCE(b.`total_deductions`, 0) + (
        SELECT COALESCE(SUM(COALESCE(p.`late_deduction`, 0) + COALESCE(p.`absence_deduction`, 0)), 0)
        FROM `payslips` p WHERE p.`payroll_batch_id` = b.`id`
    ),
    b.`remarks` = NULL
WHERE b.`id` BETWEEN 1 AND 7 AND b.`batch_type` = 'regular';

UPDATE `payslips`
SET `daily_rate_used` = ROUND(COALESCE(`hourly_rate_used`, 0) * 8, 2)
WHERE `employment_type` = 'Full-time'
  AND `payslip_type` = 'regular'
  AND COALESCE(`daily_rate_used`, 0) = 0;
